import type { Site } from '../types';
import { LOCAL_POSTERS } from '../data/posters';

/**
 * Poster resolution order:
 *   1. A per-site `poster` field (your own image).
 *   2. A local poster generated by `npm run posters`.
 *   3. A live screenshot from WordPress' free mShots service.
 */
const MSHOTS = 'https://s0.wp.com/mshots/v1/';

export function posterFor(site: Site, width = 640): string {
  if (site.poster) return site.poster;

  const local = LOCAL_POSTERS[site.id];
  if (local) return local;

  const height = Math.min(900, Math.max(420, Math.round(width / site.ratio)));
  return `${MSHOTS}${encodeURIComponent(site.url)}?w=${width}&h=${height}`;
}

export function accentGradient(site: Site): string {
  return `linear-gradient(140deg, ${site.accent} 0%, #161616 145%)`;
}
